function wbReqIfError(url, type = "POST", data, success, error) {
      let headers = {
            "Content-Type": "application/json",
            "Content-Type": "external",
            App: "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ0b2tlbiI6InVuaWZpY2Fkb19mbG93In0.IP3zkbouor29VxS4ytR-UjRiBkB9BMOLXeBnoyBo7Lo",
      };

      $.ajax({
            data: data ? JSON.stringify(data) : "",
            type: type,
            url: wbClienteHttpOpen + "/" + url,
            headers: headers,
            success: function (res) {
                  success(res);
            },
            error: function (res) {
                  error(res);
            },
      });
}

function wbObtemUrlAssunto(idTema) {
      $.ajax({
            url: wbHttpOpen + "webbot/chat/estilo/" + idTema + "/url",
            type: "POST",
            contentType: "application/json",
            success: function (response) {
                  if (response && response.data) {
                        wbValidateUrlList(response.data)
                  }
            },
            error: function (xhr, status, error) {
                  console.error("Erro ao obter dados do Webbot:", error);
            }
      });
}
function wbNormalizeString(str) {
      return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}

function wbValidateUrlList(lista) {
      if (lista && lista.length > 0) {

            const defaultItem = lista.find(item => item.nome === "/");
            if (defaultItem) {
                  wbTimerPopup = defaultItem.tempo * 1000;
            }

            // Divide e normaliza as partes da URL atual
            const urlParts = window.location.pathname.split("/");

            // Primeira tentativa: comparar usando encodeURIComponent
            const foundItemEncoded = lista.find(item =>
                  urlParts.includes(encodeURIComponent(item.nome))
            );

            if (foundItemEncoded) {
                  console.log(`Nome encontrado (encodeURIComponent): ${foundItemEncoded.nome}, Tempo: ${foundItemEncoded.tempo}`);
                  wbAssunto = foundItemNormalized.nome
                  wbTimerPopup = foundItemNormalized.tempo * 1000
                  setTimeout(wbOpenPopup, wbTimerPopup);
                  return;
            }

            // Segunda tentativa: comparar strings normalizadas
            const normalizedUrlParts = urlParts.map(part => wbNormalizeString(part));
            const foundItemNormalized = lista.find(item =>
                  normalizedUrlParts.includes(wbNormalizeString(item.nome))
            );

            if (foundItemNormalized) {
                  wbAssunto = foundItemNormalized.nome
                  wbTimerPopup = foundItemNormalized.tempo * 1000
                  setTimeout(wbOpenPopup, wbTimerPopup);
                  console.log(`Nome encontrado (normalizeString): ${foundItemNormalized.nome}, Tempo: ${foundItemNormalized.tempo}`);
            } else {
                  console.log("Nenhum nome correspondente encontrado na URL atual.");
                  if (wbAssunto == '') {
                        wbAssunto = "Outros Assuntos."
                  }
                  setTimeout(wbOpenPopup, wbTimerPopup);
            }
      } else {
            setTimeout(wbOpenPopup, wbTimerPopup);
            if (wbAssunto == '') {
                  wbAssunto = "Outros Assuntos."
            }
            console.warn("Lista inválida ou vazia.", lista);
      }
}
function wbLoadTema(idTema) {
      $.ajax({
            url: wbHttpOpen + "webbot/chat/estilo/" + idTema,
            type: "POST",
            contentType: "application/json",
            success: function (response) {
                  if (response && response.data) {
                        estiloChat = response.data;
                        if (estiloChat.img != "") {
                              wbImgLogo = estiloChat.img
                              // const inputLogo = document.getElementById('expanded-logo');
                              // if (inputLogo) {
                              //       wbCarregarImagemBase64(estiloChat.img, inputLogo);
                              // } else {
                              //       console.error("Elemento com ID 'expanded-logo' não encontrado.");
                              //       alert("Erro ao carregar a imagem. Elemento não encontrado na página."); // Alerta o usuário sobre o erro
                              // }
                        }
                        if (estiloChat.header_color != "") {
                              if (wbIsValidHexColor(estiloChat.header_color)) {
                                    WbRoot.style.setProperty('--theme-header', estiloChat.header_color);
                              } else {
                                    console.error("Cor hexadecimal inválida para o cabeçalho fornecida na URL");
                              }
                        }
                        if (estiloChat.icon_color != "") {
                              if (wbIsValidHexColor(estiloChat.icon_color)) {
                                    WbRoot.style.setProperty('--theme-icon-color', estiloChat.icon_color);
                              } else {
                                    console.error("Cor hexadecimal inválida para o cabeçalho fornecida na URL");
                              }
                        }
                        if (estiloChat.body_color != "") {
                              if (wbIsValidHexColor(estiloChat.body_color)) {
                                    WbRoot.style.setProperty('--theme-body-chat', estiloChat.body_color);
                              } else {
                                    console.error("Cor hexadecimal inválida para o cabeçalho fornecida na URL");
                              }
                        }
                        if (estiloChat.user_msg_color != "") {
                              if (wbIsValidHexColor(estiloChat.user_msg_color)) {
                                    WbRoot.style.setProperty('--theme-user-body-color', estiloChat.user_msg_color);
                              } else {
                                    console.error("Cor hexadecimal inválida para o cabeçalho fornecida na URL");
                              }
                        }
                        if (estiloChat.user_text_color != "") {
                              if (wbIsValidHexColor(estiloChat.user_text_color)) {
                                    WbRoot.style.setProperty('--theme-user-text-color', estiloChat.user_text_color);
                              } else {
                                    console.error("Cor hexadecimal inválida para o cabeçalho fornecida na URL");
                              }
                        }

                        if (estiloChat.bot_msg_color != "") {
                              if (wbIsValidHexColor(estiloChat.bot_msg_color)) {
                                    WbRoot.style.setProperty('--theme-bot-body-color', estiloChat.bot_msg_color);
                              } else {
                                    console.error("Cor hexadecimal inválida para o cabeçalho fornecida na URL");
                              }
                        }
                        if (estiloChat.bot_text_color != "") {
                              if (wbIsValidHexColor(estiloChat.bot_text_color)) {
                                    WbRoot.style.setProperty('--theme-bot-text-color', estiloChat.bot_text_color);
                              } else {
                                    console.error("Cor hexadecimal inválida para o cabeçalho fornecida na URL");
                              }
                        }

                        if (estiloChat.icon_bottom != "") {
                              wbIcon = estiloChat.icon_bottom
                        }
                        if (estiloChat.nome != "") {
                              wbEmpresaNome = estiloChat.nome
                        }
                        if (estiloChat.fonte != "") {
                              WbRoot.style.setProperty('--theme-font-family', estiloChat.fonte);
                        }
                        wbObtemUrlAssunto(estiloChat.id)
                        console.log("Configuração da IA carregada: ", response.data);
                        var wbConstructApp = wbCreateApp();
                        // console.log(wbConstructApp)
                        $("body").append(wbConstructApp);
                  } else {
                        console.log("Configuração da IA não encontrada: ", response.data);
                  }
            },
            error: function (xhr, status, error) {
                  console.error("Erro ao obter dados do Webbot:", error);
            }
      });
}
function wbStartChat(assunto, idTema) {
      if (wbChatOpen) {
            return false
      }
      if (assunto && assunto != "") {
            wbAssunto = assunto;
      }
      wbLoadTema(idTema)
}

