function wbCreateApp() {
      wbChatApp = $('<div></div>').attr('class', 'wbChatApp');
      wbChatContent = wbCreateChatContent();
      var wbChatLoader = $('<div>', {
            id: 'loaderMsg',
            class: 'spinner-grow text-secondary',
            css: {
                  width: '100%',
                  textAlign: 'center',
                  display: 'none',
                  animation: 'blink 1s linear infinite',
                  '-webkit-animation': 'blink 1s linear infinite'
            }
      });
      var spn = $('<div>', { id: 'loading-dots', text: "..." });
      wbChatLoader.append(spn);

      $(wbChatContent).append(wbCreateHeader());
      $(wbChatContent).append(wbCreateBody());
      $(wbChatContent).append(wbChatLoader);
      $(wbChatContent).append(wbCreateFooter());
      $(wbChatContent).append(wbCreateModalOverlay());
      $(wbChatApp).append(wbChatContent);
      var wbChatToggler = $('<a id="wbChatToggler" class="wbNormalize"><i class="wbChatToggler wb-solid wb-comment-dots"></i></a>').attr("id", "wbChatToggler");
      $(wbChatApp).append(wbChatToggler);
      return wbChatApp;
}

