function wbCreateModalOverlay() {
      var wbModalOverlay = $('<div></div>').addClass('wbModalOverlay');

      // Modal de Configurações de Fonte
      var wbModalFontOverlayModal = $('<div></div>').addClass('wbFontModal');
      wbModalFontOverlayModal.append($('<h3>Configurações de Acessibilidade</h3>'));

      // Campo de Tamanho de Fonte
      var fontSizeFieldset = $('<fieldset></fieldset>').addClass('mb-1');
      fontSizeFieldset.append($('<legend>Tamanho da Fonte</legend>'));
      fontSizeFieldset.append($('<label id="wbSizeExemple" for="wbFontInput">Ajuste o tamanho:</label>'));
      fontSizeFieldset.append($('<input type="range" min="12" max="20" value="16" id="wbFontInput">'));
      wbModalFontOverlayModal.append(fontSizeFieldset);

      // Campo de Tipo de Fonte
      var fontTypeFieldset = $('<fieldset></fieldset>').addClass('mb-1');
      fontTypeFieldset.append($('<legend>Tipo de Fonte</legend>'));
      fontTypeFieldset.append($('<p><label for="wbFontSelect" id="wbFontExemple">Escolha a fonte: </label></p>'));
      var wbFontSelect = $('<select></select>').attr('id', 'wbFontSelect').addClass("form-control");
      wbFontSelect.append('<option value="Roboto">Roboto</option>');
      wbFontSelect.append('<option value="Arial">Arial</option>');
      wbFontSelect.append('<option value="Verdana">Verdana</option>');
      wbFontSelect.append('<option value="Tahoma">Tahoma</option>');
      wbFontSelect.append('<option value="Times New Roman">Times New Roman</option>');
      wbFontSelect.append('<option value="Georgia">Georgia</option>');
      wbFontSelect.append('<option value="Courier New">Courier New</option>');
      fontTypeFieldset.append(wbFontSelect);
      wbModalFontOverlayModal.append(fontTypeFieldset);

      // Botões de Ação
      wbModalFontOverlayModal.append($('<span class="wbModalClose" onclick="wbFecharModal()">×</span>'));
      wbModalFontOverlayModal.append($('<button class="wb-button-60" onclick="wbSalvarFont()">Salvar</button>'));

      wbModalOverlay.append(wbModalFontOverlayModal);

      var wbModalOverlayModal = $('<div></div>').addClass('wbModal');

      wbModalOverlayModal.append($('<h2>Envio de Arquivo</h2>'));
      wbModalOverlayModal.append($('<input type="file" accept=".png, .jpg, .jpeg, .pdf, .ods, .xlsx, .xls, .csv" id="wbFileInput">'));
      wbModalOverlayModal.append($('<span class="wbModalClose" onclick="wbFecharModal()">×</span>'));
      wbModalOverlayModal.append($('<button class="wb-button-60" onclick="wbEnviarArquivo()">Enviar</button>'));

      wbModalOverlay.append(wbModalOverlayModal);
      return wbModalOverlay;
}

function wbSalvarFont() {
      // Obtém os valores do seletor de tamanho e tipo de fonte
      var fontSize = $('#wbFontInput').val() + 'px';
      var fontFamily = $('#wbFontSelect').val();

      // Aplica o tamanho e o tipo de fonte no elemento do chat
      $('.wbChatApp .wbChatContent').css({ 'font-size': fontSize, 'font-family': fontFamily });
      $('.wbChatApp .wbChatConversa').css({ 'font-size': fontSize, 'font-family': fontFamily });


      // Fecha o modal
      wbFecharModal();
}

function wbCreateFooter() {
      var wbChatFooter = $('<div></div>').addClass('wbChatFooter');
      var wbFileFild = $('<a></a>')
            .attr('id', 'wbBtnFile')
            .addClass('wb-fab')
            .attr('onclick', "$('.wbModalOverlay, .wbModal').fadeIn()")
            .append($('<i></i>').addClass('wb-solid wb-paperclip'));
      var wbSendFild = $('<a></a>')
            .attr('id', 'wbBtnSend')
            .attr('onclick', 'wbEnviarMensagem()')
            .addClass('wb-fab')
            .append($('<i></i>').addClass('wb-solid wb-paper-plane'));
      var wbTextFild = $('<input>')
            .attr({
                  'id': 'wbTextFild',
                  'name': 'wbTextFild',
                  'class': 'wbTextFild wbTextArea',
                  'placeholder': 'Digite sua Mensagem.'
            })
            .prop('disabled', true);
      $(wbChatFooter).append(wbFileFild);
      $(wbChatFooter).append(wbTextFild);
      $(wbChatFooter).append(wbSendFild);
      return wbChatFooter;
}
function wbStartLoopLoader(bl) {
      if (bl) {
            $("#loaderMsg").show(100)
            wbStartLoadingDotsAnimation();
      } else {
            $("#loaderMsg").hide(100)
            wbStopLoadingDotsAnimation();
      }
}

