function wbEnviarMensagem(seTexto) {
      if (WbEnviaFormValidade) {
            if (seTexto) {
                  textoCliente = seTexto;
            } else {
                  if (wbChatOpen == true) {
                        textoCliente = $('#wbTextFild').val();
                  } else {
                        textoCliente = "Gostaria de conversar via Chat";
                  }
            }
            $('#wbTextFild').val('');
            if (textoCliente != '') {
                  var now = new Date(Date.now());
                  var data = {
                        "Mensage": {
                              "From": {
                                    "Type": "Cliente",
                                    "Nome": "Cliente WebChat",
                                    "ID": wbClientId
                              },
                              "Data": {
                                    "Type": "text",
                                    "Texto": textoCliente,
                              },
                              "Timestamp": Date.now()
                        },
                        "EmpresasId": wbEmpresaId,
                        "Funcao": "sendMensageClientWeb",
                        "WsConn": idConexao,
                        "Number": String(wbGlobIpClient),
                        "Timestamp": Date.now()
                  };
                  if (wbChatOpen == true) {
                        wbChatBodyMsgUser = $('<div></div>').attr('class', 'chat_msg_item_user chat_msg_item wbChatBodyStyle');
                        $(wbChatBodyMsgUser).append('<p>' + data.Mensage.Data.Texto + '</p>');
                        $(wbChatConversa).append(wbChatBodyMsgUser);
                  } else {
                        wbChatOpen = true
                  }
                  wbSendMsg(data);
                  wbScrollBot()
            }
      }
}
function wbSendMsg(data) {
      if (WbEnviaFormValidade) {
            $('#wbTextFild').prop("disabled", true);
            let seter = {
                  Funcao: 'sendMensageClientWeb',
                  Number: data.Number,
                  WsConn: idConexao,
                  FluxoID: wbFluxoId,
                  Mensage: data.Mensage,
                  EmpresasId: data.EmpresasId,
                  "DadosCliente": {
                        "Email": wbEmailInfo,
                        "CpfCnpj": wbDocumentoInfo,
                        "Telefone": wbTelefoneInfo,
                        "Cidade": wbCidadeInfo,
                        "Pais": wbPaisInfo,
                        "Estado": wbEstadoInfo,
                        "Reclame": wbReclameInfo
                  }
            };
            Wbws.send(JSON.stringify(seter));
            $('#wbTextFild').prop("disabled", false);
            wbStartLoopLoader(true)
            $('#wbTextFild').focus();
      }
}

function wbEnviarFormMensagem() {
      let documento = $('#WBatendimentoFormCpf').val().trim().replace(/\D/g, ''); // Remove todos os não-dígitos
      let tel = $('#WBatendimentoFormTelefone').val().trim().replace(/\D/g, ''); // Remove todos os não-dígitos
      let email = $('#WBatendimentoFormEmail').val().trim();
      let pais = $('#WBatendimentoFormPais').val().trim();
      let estado = $('#WBatendimentoFormEstado').val().trim();
      let municipio = $('#WBatendimentoFormMunicipio').val().trim();
      const regexEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      validateFormInicial = true;
      let reclamacao = $('input[name="Reclamacao"]:checked').val() ? $('input[name="Reclamacao"]:checked').val() : 'nao';

      const regexTelefone = /^(55)?(\d{2})(\d{8,9})$/;
      // Expressões regulares para validar CPF (11 dígitos) e CNPJ (14 dígitos)
      const regexCPF = /^\d{11}$/;
      const regexCNPJ = /^\d{14}$/;
      validateFormInicial = true
      if (regexTelefone.test(tel)) {
            // Se o telefone for válido, remove o campo de mensagem e inicia o processo
            $('#WBatendimentoFormTelefoneError').remove();
            wbTelefoneInfo = tel; // Armazena o documento
      } else {
            validateFormInicial = false

            // Se o telefone for inválido, exibe uma mensagem de erro
            $('#WBatendimentoFormTelefoneError').text('Número de telefone inválido. Por favor, insira um número válido.');
      }
      // Verifica se o documento é CPF ou CNPJ válido
      if (regexCPF.test(documento) || regexCNPJ.test(documento)) {
            // Se o documento for válido, remove o campo de mensagem e inicia o processo
            $('#WBatendimentoFormCpfError').remove();
            wbDocumentoInfo = documento; // Armazena o documento
      } else {
            validateFormInicial = false
            // Se o documento for inválido, exibe uma mensagem de erro
            $('#WBatendimentoFormCpfError').text('Documento inválido. Por favor, insira um CPF (11 dígitos) ou CNPJ (14 dígitos) válido.');
      }


      if (regexEmail.test(email)) {
            $('#WBatendimentoFormEmailError').remove();
      } else {
            validateFormInicial = false;
            $('#WBatendimentoFormEmailError').text('Email inválido. Por favor, insira um email válido.');
      }
      // Validação da cidade (pelo menos 2 caracteres)
      if (pais.length >= 2) {
            $('#WBatendimentoFormPaisError').remove();
      } else {
            validateFormInicial = false;
            $('#WBatendimentoFormPaisError').text('Pais inválido. Por favor, insira o Pais.');
      }
      // Validação da cidade (pelo menos 2 caracteres)
      if (estado.length >= 2) {
            $('#WBatendimentoFormEstadoError').remove();
      } else {
            validateFormInicial = false;
            $('#WBatendimentoFormEstadoError').text('Estado inválido. Por favor, insira o Estado.');
      }
      // Validação da cidade (pelo menos 2 caracteres)
      if (municipio.length >= 2) {
            $('#WBatendimentoFormMunicipioError').remove();
      } else {
            validateFormInicial = false;
            $('#WBatendimentoFormMunicipioError').text('Cidade inválida. Por favor, insira a Cidade.');
      }

      // Validação do radio button
      if (reclamacao) {
            $('#WBatendimentoFormReclamacaoError').text('').removeClass('show-error');
      } else {
            validateFormInicial = false;
            $('#WBatendimentoFormReclamacaoError').text('Por favor, selecione uma opção.').addClass('show-error');
      }
      if (validateFormInicial) {
            wbEmailInfo = email; // Armazena o documento
            wbCidadeInfo = municipio;
            wbPaisInfo = pais;
            wbEstadoInfo = estado;
            wbReclameInfo = reclamacao;
            wbInitWSForm(true);
            $('#WBatendimentoFormMsg').remove();
      }
}
