function wbEnviarArquivo() {
      wbMediaInput = $('#wbFileInput')[0].files[0];
      if (wbMediaInput) {
            var wbReader = new FileReader();
            wbReader.onload = function (e) {
                  var base64Content = e.target.result.split(',')[1];
                  var now = new Date(Date.now());
                  typeSend = "image";
                  if (wbMediaInput.type.indexOf("application") !== -1) {
                        typeSend = "application";
                  }

                  // Extract filename from the file object
                  const filename = wbMediaInput.name;

                  var data = {
                        "Mensage": {
                              "From": {
                                    "Type": "Cliente",
                                    "Nome": "Cliente WebChat",
                                    "ID": wbClientId
                              },
                              "Data": {
                                    "Type": typeSend,
                                    "Texto": "",
                                    "Media": {
                                          "base_data": base64Content,
                                          "mime_type": wbMediaInput.type
                                    }
                              },
                              "Timestamp": Date.now()
                        },
                        "EmpresasId": wbEmpresaId,
                        "Funcao": "sendMensageClientWeb",
                        "WsConn": idConexao,
                        "Number": String(wbGlobIpClient),
                        "Timestamp": Date.now()
                  };

                  wbChatBodyMsgUser = $('<div></div>').attr('class', 'chat_msg_item_user chat_msg_item wbChatBodyStyle');
                  if (wbMediaInput.type.indexOf("application") !== -1) {
                        let wbMsgBotPdf = $('<a></a>')
                              .attr('class', 'wbMsgBotPdf')
                              .attr("target", "_blank")
                              .attr("href", ('data:' + wbMediaInput.type + ';base64,' + base64Content))
                        if (wbMediaInput.type.indexOf("pdf") == -1) {
                              wbMsgBotPdf.attr("download", filename)
                        }
                        wbMsgBotPdf.append(filename);
                        $(wbChatBodyMsgUser).append(wbMsgBotPdf);
                  } else if (wbMediaInput.type.indexOf("image") !== -1) {
                        $(wbChatBodyMsgUser).append('<img alt="105x105" class="wbMsgBotImg img-responsive w-100" src="data:' + wbMediaInput.type + ';charset=utf8;base64,' + base64Content + '"/>');
                  } else if (wbMediaInput.type.indexOf("text/csv") !== -1) {
                        let wbMsgBotPdf = $('<a></a>')
                              .attr('class', 'wbMsgBotPdf')
                              .attr("target", "_blank")
                              .attr("href", ('data:' + wbMediaInput.type + ';base64,' + base64Content))
                              .attr("download", filename)
                              .append(filename);
                        $(wbChatBodyMsgUser).append(wbMsgBotPdf);
                  }
                  $(wbChatConversa).append(wbChatBodyMsgUser);
                  wbSendMsg(data);
                  wbScrollBot();
            };
            wbReader.readAsDataURL(wbMediaInput);
      }
      wbFecharModal();
}
function wbSetMsgCliente() {
      let dt = new Date(dados['Timestamp'] * 1000);
      lastMsg = dt.toLocaleString("en-US", { year: "numeric", month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }).replace(',', '');
      dt = dt.toLocaleString("pt-BR", { day: "numeric", month: "numeric", hour: "2-digit", minute: "2-digit" });
      clientesEmAtendimento[dados['ConversasId']].conversa.push(dados['Mensage'])
      if (conversaAtual == dados['ConversasId']) {
            let text;
            text = dados['Mensage'].Data.Texto;
            if (dados['Mensage'].Data.Media && dados['Mensage'].Data.Media.mimetype == 'image/jpeg') {
                  text = '<img alt="105x105" class="img-responsive w-100" src="data:' + dados['Mensage'].Data.Media.mimetype + ';charset=utf8;base64,' + dados['Mensage'].Data.Media.jpegThumbnail + '"/>';
            }
            addHtmlUsuario(text, dt, dados['Mensage'].From.Nome);
            wbScrollBot();
      } else {
            $('#listaOperador #' + dados['ConversasId']).addClass('bg-warning-ring');
      }
      $('#' + dados['ConversasId'] + ' .lasttime').attr("data-lestmsg", lastMsg);
}
function wbsetMsgBot(dados) {
      let urlRegex = /\b(https?|ftp|file):\/\/[^\s<>(){}'"\\^`|]*[^\s<>(){}'"\\^`|.,;:?!]/ig;

      switch (dados.Data.Type) {
            case 'text':
                  nomeFrom = "";
                  if (dados.From.Type == "Atendente") {
                        var partesNome = dados.From.Nome.split(" ");
                        if (partesNome.length > 0) {
                              nomeFrom = partesNome[0]; // Obtém o primeiro nome
                        } else {
                              nomeFrom = dados.From.Nome; // Usa o nome completo se não houver partes
                        }
                  } else {
                        nomeFrom = dados.From.Nome;
                  }
                  textoProcessado = dados.Data.Texto;
                  textoProcessado = textoProcessado.replace(urlRegex, function (url) {
                        return '<a href="' + url + '" target="_blank" class="wbChatLink">' + url + '</a>';
                  });
                  textoProcessado = textoProcessado.replaceAll("\n", "<br/>");
                  wbChatBodyMsgBot = $('<div></div>').attr('class', 'chat_msg_item_admin chat_msg_item wbChatBodyStyle');
                  $(wbChatBodyMsgBot).append('<h4 class="wbTitleMensage"><strong>' + nomeFrom + '</strong></h4><p>' + textoProcessado + '</p>');
                  $(wbChatConversa).append(wbChatBodyMsgBot);
                  break;
            case 'list':
                  textoProcessado = dados.Data.Texto;
                  textoProcessado = textoProcessado.replace(urlRegex, function (url) {
                        return '<a href="' + url + '" target="_blank" class="wbChatLink">' + url + '</a>';
                  });
                  textoProcessado = textoProcessado.replaceAll("\n", "<br/>");
                  wbChatBodyMsgBot = $('<div></div>').attr('class', 'chat_msg_item_admin chat_msg_item wbChatBodyStyle');
                  $(wbChatBodyMsgBot).append('<h4 class="wbTitleMensage"><strong>' + dados.From.Nome + '</strong></h4><p>' + textoProcessado + '</p>');
                  let wbMsgBotUl = $('<ul></ul>').attr('class', 'wbMsgUlList');

                  // Verificar se a lista contém mais de 3 itens
                  let options = dados.Data.Menus.Options;
                  if (options.length > 3) {
                        // Ordenar os elementos por Index de forma decrescente
                        options = options.sort((a, b) => b.Index - a.Index);
                  }

                  // Criar os itens da lista
                  options.forEach(element => {
                        let wbMsgBotLi = $('<li>' + element.Texto.replaceAll("\n", "<br/>") + '</li>')
                              .attr('class', 'wbMsgLiItemList')
                              .attr('data-element', (element.Index ? element.Index + ' para ' : '') + element.Texto.replaceAll("\n", "<br/>"))
                              .attr('onclick', 'wbSelectListItem(this,\'' + dados.ID + '\')');
                        wbMsgBotUl.append(wbMsgBotLi);
                  });

                  $(wbChatBodyMsgBot).append(wbMsgBotUl);
                  $(wbChatConversa).append(wbChatBodyMsgBot);
                  break;

            case 'image':
                  wbChatBodyMsgBot = $('<div></div>').attr('class', 'chat_msg_item_admin chat_msg_item wbChatBodyStyle');
                  let wbMsgBotImg = $('<img>').attr('class', 'wbMsgBotImg').attr("src", ('data:' + dados.Data.Media.MimeType + ';base64,' + dados.Data.Media.Base64));
                  $(wbChatBodyMsgBot).append(wbMsgBotImg);
                  $(wbChatBodyMsgBot).append('<p>' + dados.Data.Texto.replaceAll("\n", "<br/>") + '</p>');
                  $(wbChatConversa).append(wbChatBodyMsgBot);
                  break;
            case 'application':
                  wbChatBodyMsgBot = $('<div></div>').attr('class', 'chat_msg_item_admin chat_msg_item wbChatBodyStyle');
                  $(wbChatBodyMsgBot).append('<h4 class="wbTitleMensage"><strong>' + dados.From.Nome + '</strong></h4>')
                  let wbMsgBotPdf = $('<a></a>').attr('class', 'wbMsgBotPdf').attr("target", "_blank").attr("href", ('data:' + dados.Data.Media.MimeType + ';base64,' + dados.Data.Media.Base64));
                  wbMsgBotPdf.append("Abrir PDF")
                  $(wbChatBodyMsgBot).append(wbMsgBotPdf);
                  $(wbChatBodyMsgBot).append('<p>' + dados.Data.Texto.replaceAll("\n", "<br/>") + '</p>');
                  $(wbChatConversa).append(wbChatBodyMsgBot);
                  break;
            default:
                  break;
      }
      wbStartLoopLoader(false)
      wbScrollBot()
}
function wbSelectListItem(e, menuId) {
      const textoCliente = $(e).attr('data-element');
      $('.wbMsgUlList li').attr('onclick', '');
      $(e).attr('class', 'active')
      $('#wbTextFild').val('');
      if (textoCliente != '') {
            var now = new Date(Date.now());
            var data = {
                  "Mensage": {
                        "From": {
                              "Type": "Cliente",
                              "Nome": wbClientNome,
                              "ID": wbClientId
                        },
                        "Data": {
                              "Type": "text",
                              "Texto": textoCliente,
                        },
                        "Timestamp": Date.now()
                  },
                  "EmpresasId": wbEmpresaId,
                  "Funcao": "sendMensageClientWeb",
                  "WsConn": idConexao,
                  "Number": String(wbGlobIpClient),
                  "Timestamp": Date.now()
            };
            if (wbChatOpen == true) {
                  wbChatBodyMsgUser = $('<div></div>').attr('class', 'chat_msg_item_user chat_msg_item wbChatBodyStyle');
                  $(wbChatBodyMsgUser).append('<p>' + data.Mensage.Data.Texto + '</p>');
                  $(wbChatConversa).append(wbChatBodyMsgUser);
            } else {
                  wbChatOpen = true
            }
            wbSendMsg(data);
            wbScrollBot()
      }
}

//tools
function wbStartLoadingDotsAnimation() {
      wbLoadingDotsInterval = setInterval(function () {
            wbDotsCount++;
            if (wbDotsCount > 20) { // Limite máximo de pontos
                  wbDotsCount = 3; // Reinicia a contagem
            }
            $("#loading-dots").text(".".repeat(wbDotsCount)); // Atualiza o texto com o número atual de pontos
      }, 200); // Intervalo de atualização (200ms = 0.2 segundos)
}
function wbStopLoadingDotsAnimation() {
      clearInterval(wbLoadingDotsInterval); // Limpa o intervalo para parar a animação
      wbDotsCount = 3; // Reseta o contador
      $("#loading-dots").text("..."); // Reseta o texto para os 3 pontos iniciais
}
function wbScrollBot() {
      let d = $('#wbChatBody');
      d.scrollTop(d.prop("scrollHeight"));
}
function wbIsValidHexColor(hex) {
      return /^#([0-9A-F]{3}){1,2}$/i.test(hex);
}
function wbOpenPopup() {
      if (wbChatOpen == false) {
            wbToggleApp();
      }
}
function wbToggleApp() {
      $('.wbChatToggler').toggleClass('wb-comment-dots');
      $('.wbChatToggler').toggleClass('wb-close');
      $('.wbChatToggler').toggleClass('is-active');
      $('.wbChatToggler').toggleClass('is-visible');
      $('#wbChatToggler').toggleClass('is-float');
      $('.wbChatContent').toggleClass('is-visible');
      $('.wb-fab').toggleClass('is-visible');
      if (wbChatOpenValidate == false) {
            $('.wbChatContent').show();
            wbChatOpenValidate = true
      } else {
            $('.wbChatContent').hide();
            wbChatOpenValidate = false
      }
      if (wbChatOpen == false) {
            // wbEnviarMensagem()
            wbIniciaForm()
            wbChatOpen = true;
      }
}
function wbHideChat(hide) {
      switch (hide) {
            case 0:
                  $('#chat_converse').css('display', 'none');
                  $('#wbChatBody').css('display', 'none');
                  $('#chat_form').css('display', 'none');
                  $('.chat_login').css('display', 'block');
                  $('#chat_fullscreen').css('display', 'none');
                  break;
            case 1:
                  $('#chat_converse').css('display', 'block');
                  $('#wbChatBody').css('display', 'none');
                  $('#chat_form').css('display', 'none');
                  $('.chat_login').css('display', 'none');
                  break;
            case 2:
                  $('#chat_converse').css('display', 'none');
                  $('#wbChatBody').css('display', 'block');
                  $('#chat_form').css('display', 'none');
                  $('.chat_login').css('display', 'none');
                  break;
            case 3:
                  $('#chat_converse').css('display', 'none');
                  $('#wbChatBody').css('display', 'none');
                  $('#chat_form').css('display', 'block');
                  $('.chat_login').css('display', 'none');
                  break;
            case 4:
                  $('#chat_converse').css('display', 'none');
                  $('#wbChatBody').css('display', 'none');
                  $('#chat_form').css('display', 'none');
                  $('.chat_login').css('display', 'none');
                  $('#chat_fullscreen').css('display', 'block');
                  break;
      }
}
function wbFecharModal() {
      $('.wbModalOverlay, .wbModal').fadeOut();
      $('.wbModalOverlay, .wbFontModal').fadeOut();
}

function wbPing() {
      setTimeout(function () {
            var data = {
                  Funcao: 'ping',
            };
            Wbws.send(JSON.stringify(data));
            wbPing();
      }, 45000);
}
function wbGetIp() {
      try {
            $.get('https://www.cloudflare.com/cdn-cgi/trace', function (data) {
                  data = data.trim().split('\n').reduce(function (obj, pair) {
                        pair = pair.split('=');
                        return obj[pair[0]] = pair[1], obj;
                  }, {});
                  wbGlobIpClient = data.ip + '' + Math.random() + Math.floor(Math.random() * 9999999) + 1 + '.' + wbCheckDate.getDate() + '.' + (wbCheckDate.getMonth() + 1) + '.' + wbCheckDate.getFullYear() + '.' + wbCheckDate.getHours() + '.' + wbCheckDate.getMinutes() + '.' + wbCheckDate.getSeconds();
            }, fail(function () {
                  wbGlobIpClient = Math.random() + Math.floor(Math.random() * 9999999) + 1 + '.' + wbCheckDate.getDate() + '.' + (wbCheckDate.getMonth() + 1) + '.' + wbCheckDate.getFullYear() + '.' + wbCheckDate.getHours() + '.' + wbCheckDate.getMinutes() + '.' + wbCheckDate.getSeconds();
            }), error(function () {
                  wbGlobIpClient = Math.random() + Math.floor(Math.random() * 9999999) + 1 + '.' + wbCheckDate.getDate() + '.' + (wbCheckDate.getMonth() + 1) + '.' + wbCheckDate.getFullYear() + '.' + wbCheckDate.getHours() + '.' + wbCheckDate.getMinutes() + '.' + wbCheckDate.getSeconds();
            }));
      } catch (e) {

      }
}
function wbValidarCpfCnpj(cpfCnpj) {
      var cpfCnpjRegex = /^\d{11}$|^\d{14}$/;
      return cpfCnpjRegex.test(cpfCnpj);
}
function wbValidarEmail(email) {
      var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return emailRegex.test(email);
}
function wbCarregarImagemBase64(base64String, inputElement) {

      if (!base64String) {
            return; // Sai da função se a string base64 estiver vazia
      }
      const img = new Image();
      img.onload = function () {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);

            canvas.toBlob(function (blob) {
                  const file = new File([blob], "image.jpg", { type: 'image/jpeg' }); // Cria um novo File

                  const dataTransfer = new DataTransfer();
                  dataTransfer.items.add(file);
                  inputElement.files = dataTransfer.files;

            }, 'image/jpeg');
      };
      img.onerror = function () {
            console.error("Erro ao carregar imagem base64:", base64String);
            alert("Erro ao carregar a imagem. Verifique o formato do arquivo."); // Alerta o usuário sobre o erro
      };
      img.src = base64String;
}

function mostrarTelaSeHorarioPermitido() {
      // Obter a data e hora atual
      const agora = new Date();
      
      // Pegar a hora atual
      const horaAtual = agora.getHours();
      
      // Pegar o dia da semana atual (0 = Domingo, 6 = Sábado)
      const diaSemanaAtual = agora.getDay();
      
      // Definir o intervalo de horas permitido (9:00 às 19:00)
      const horaInicio = 9;
      const horaFim = 20;
      
      // Verificar se é final de semana (sábado = 6 ou domingo = 0)
      const isFinalDeSemana = (diaSemanaAtual === 0 || diaSemanaAtual === 6);
  
      const isFeriadoHoje = isFeriado(agora);
      // Retorna true se estiver no horário permitido
      return (horaAtual >= horaInicio && horaAtual < horaFim && !isFinalDeSemana && !isFeriadoHoje);
}
function isFeriado(data) {
      // Lista de feriados no formato "MM-DD" para o ano todo
      const feriados = [
          "01-01", // Ano Novo
          "04-21", // Tiradentes
          "05-01", // Dia do Trabalhador
          "09-07", // Independência do Brasil
          "10-12", // Nossa Senhora Aparecida
          "11-02", // Finados
          "11-15", // Proclamação da República
          "11-20", // Conciencia Negra
          "12-24", // Vespera Natal
          "12-25",  // Natal
          "12-31"  // Vespera de Ano Novo
      ];
      
      const mesDia = `${String(data.getMonth() + 1).padStart(2, '0')}-${String(data.getDate()).padStart(2, '0')}`;
      return feriados.includes(mesDia);
}

